83	    {% if e.inmate.photo_filename %}
84	    <span class="court-card-photo">
85	      <img src="{{ base_url }}/photos/{{ e.inmate.photo_filename }}" alt="" loading="lazy" decoding="async">
86	    </span>
87	    {% else %}
88	    <span class="court-card-photo court-card-photo-placeholder" aria-hidden="true" data-initials="{{ avatar_initials(e.inmate.full_name) }}"></span>
